UPDATE alternate_record
SET status = #{status}, updated_at = #{updateTime}

    , promoted_time = #{updateTime}


    , expired_time = #{updateTime}

WHERE patient_id = #{patientId} AND sch_id = #{schId}

mapper.select:
SELECT patient_id AS patientId, sch_id AS schId, status, waiting_time AS waitingTime, promoted_time AS promotedTime, expired_time AS expiredTime, position, created_at AS createdAt, updated_at AS updatedAt FROM alternate_record WHERE sch_id = #{schId}
AND status = #{status}
ORDER BY waiting_time ASC

mapper.update:
UPDATE alternate_record 
SET status = '已过期', expired_time = #{expiredTime}, updated_at = #{expiredTime}
WHERE sch_id = #{schId} AND status = '候补中'

UPDATE alternate_record 
SET status = '已转正', promoted_time = #{promotedTime}, updated_at = #{promotedTime}
WHERE patient_id = #{patientId} AND sch_id = #{schId} AND status = '候补中'

mapper.select:
SELECT COUNT(*) + 1
FROM alternate_record
WHERE sch_id = #{schId} 
  AND status = '候补中'
  AND waiting_time < (
      SELECT waiting_time FROM alternate_record 
      WHERE patient_id = #{patientId} AND sch_id = #{schId}
  )
